import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';

export default function VolunteerDonorSection({ me, events, token, setMsg, activities }) {

  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState('');
  const [selectedNgoDetails, setSelectedNgoDetails] = useState(null);
  const [showNgo, setShowNgo] = useState(false);

  useEffect(() => {
    const fetchNgos = async () => {
      try {
        const res = await fetch('http://localhost:4000/actions/my-ngos', {
          headers: { Authorization: `Bearer ${token}` }
        });
        const data = await res.json();
        setMyNgos(data.ngos || []);
      } catch (e) {
        console.error(e);
      }
    };
    fetchNgos();
  }, [token]);

  useEffect(() => {
    const fetchAchievements = async () => {
      try {
        const res = await fetch('http://localhost:4000/actions/my-achievements', {
          headers: { Authorization: `Bearer ${token}` }
        });
        const data = await res.json();
        setAchievements(data.achievements || []);
      } catch (e) {
        console.error(e);
      }
    };
    fetchAchievements();
  }, [token]);

  // When dropdown changes — fetch full selected NGO details from myNgos list
  const handleNgoSelect = (ngoId) => {
    setSelectedNgo(ngoId);
    const ngoObj = myNgos.find(n => n.id == ngoId);
    setSelectedNgoDetails(ngoObj || null);
  };

  return (
    <div className="volunteer-donor-section">

      <h2>Your NGOs</h2>

      {/* NGO SELECT DROPDOWN */}
      <select
        value={selectedNgo}
        onChange={(e) => handleNgoSelect(e.target.value)}
      >
        <option value="">Select NGO</option>
        {myNgos.map((ngo) => (
          <option key={ngo.id} value={ngo.id}>
            {ngo.name}
          </option>
        ))}
      </select>

      {/* VIEW BUTTON */}
      <button
        disabled={!selectedNgoDetails}
        onClick={() => setShowNgo(true)}
      >
        VIEW
      </button>

      {/* SHOW NGO DETAILS */}
      {showNgo && selectedNgoDetails && (
        <div className="ngo-details-panel" style={{ marginTop: "20px", padding: "15px", border: "1px solid #ccc" }}>
          <h3>{selectedNgoDetails.name}</h3>

          {selectedNgoDetails.email && <p><strong>Email:</strong> {selectedNgoDetails.email}</p>}
          {selectedNgoDetails.phone && <p><strong>Phone:</strong> {selectedNgoDetails.phone}</p>}
          {selectedNgoDetails.address && <p><strong>Address:</strong> {selectedNgoDetails.address}</p>}
          {selectedNgoDetails.description && <p><strong>Description:</strong> {selectedNgoDetails.description}</p>}

          <button onClick={() => setShowNgo(false)}>Close</button>
        </div>
      )}

      <h2>Your Activities</h2>

      <Volunteer token={token} events={events} me={me} setMsg={setMsg} />
      <Donate token={token} me={me} setMsg={setMsg} />
      <Feedback token={token} me={me} setMsg={setMsg} />

      <h2>Your Achievements</h2>
      {achievements && achievements.length > 0 ? (
        <ul>
          {achievements.map((a) => (
            <li key={a.id}>{a.title}</li>
          ))}
        </ul>
      ) : (
        <p>No achievements yet.</p>
      )}
    </div>
  );
}
